def _enrich_question(question, lesson, index):
    """Give every A Gymnasium item the metadata required by the learning loop."""
    item = dict(question)
    item.setdefault("id", f"{lesson['id']}-q{index + 1}")
    item.setdefault("skill", lesson["title"])
    item.setdefault("difficulty", 1 if index < 2 else 2 if index < 4 else 3)
    item.setdefault("representation", ("symbolic", "verbal", "application")[index % 3])
    explanation = item.get("explanation", "Ξαναδιάβασε τη θεωρία και έλεγξε κάθε βήμα.")
    item.setdefault("hints", [
        "Εντόπισε πρώτα τι δίνεται και τι ζητείται.",
        "Σύνδεσε τα δεδομένα με τον βασικό κανόνα του μαθήματος.",
    ])
    item.setdefault("optionFeedback", [
        f"Η επιλογή «{option}» δεν συμφωνεί με τον κανόνα που χρειάζεται εδώ. "
        "Πιθανότατα χρησιμοποιήθηκε λάθος δεδομένο ή παραλείφθηκε ένας έλεγχος· "
        "ξανασύνδεσε όσα δίνονται με αυτό που ζητείται."
        if option_index != item.get("correct") else ""
        for option_index, option in enumerate(item.get("options", []))
    ])
    item.setdefault("explanation", explanation)
    return item


def _complete_g7_learning_design(lesson):
    """Apply the common research-backed specification to all 60 A Gymnasium lessons."""
    if lesson.get("gradeId") != "g7":
        return

    base = lesson.get("questions", [])
    assessment = lesson.get("assessment", {}).get("questions", [])
    bank = []
    seen = set()
    for question in [*base, *assessment]:
        signature = question.get("prompt", "")
        if signature and signature not in seen:
            seen.add(signature)
            bank.append(_enrich_question(question, lesson, len(bank)))

    # The three pilot lessons keep their richer hand-authored banks below.
    worksheet = lesson.get("worksheet", {})
    solutions = lesson.get("solutions", [])
    correct_0 = bank[0]["options"][bank[0]["correct"]] if bank else ""
    correct_1 = bank[1]["options"][bank[1]["correct"]] if len(bank) > 1 else correct_0

    def plain_answer(value):
        value = value.replace("$", "").replace("\\cdot", "·").strip()
        value = re.sub(r"\\frac\{([^{}]+)\}\{([^{}]+)\}", r"\1/\2", value)
        return value

    production = [
        {
            "id": f"{lesson['id']}-input",
            "type": "input",
            "skill": lesson["title"],
            "difficulty": 2,
            "representation": "constructed-response",
            "prompt": f"Απάντησε χωρίς επιλογές: {bank[0]['prompt'] if bank else lesson['title']}",
            "acceptedAnswers": [correct_0, plain_answer(correct_0)],
            "explanation": bank[0].get("explanation", "") if bank else "",
            "hints": bank[0].get("hints", []) if bank else ["Χρησιμοποίησε τον βασικό κανόνα.", "Έλεγξε προσεκτικά το αποτέλεσμα."],
        },
        {
            "id": f"{lesson['id']}-fill",
            "type": "fill",
            "skill": lesson["title"],
            "difficulty": 2,
            "representation": "verbal",
            "prompt": f"Συμπλήρωσε την απάντηση: {bank[1]['prompt'] if len(bank) > 1 else lesson['title']}",
            "acceptedAnswers": [correct_1, plain_answer(correct_1)],
            "explanation": bank[1].get("explanation", "") if len(bank) > 1 else "",
            "hints": bank[1].get("hints", []) if len(bank) > 1 else ["Θυμήσου τον ορισμό.", "Έλεγξε τη θεωρία."],
        },
        {
            "id": f"{lesson['id']}-error",
            "type": "self-check",
            "activityKind": "error-correction",
            "skill": lesson["title"],
            "difficulty": 3,
            "representation": "error-analysis",
            "prompt": f"Εντόπισε και διόρθωσε το λάθος: {lesson.get('attention', ['Ένας μαθητής εφαρμόζει τον κανόνα χωρίς να ελέγξει τις προϋποθέσεις του.'])[0]}",
            "modelAnswer": bank[0].get("explanation", lesson.get("attention", [""])[0]) if bank else lesson.get("attention", [""])[0],
            "hints": ["Ονόμασε πρώτα τον κανόνα που παραβιάζεται.", "Γράψε τη σωστή διαδικασία και όχι μόνο το τελικό αποτέλεσμα."],
        },
        {
            "id": f"{lesson['id']}-investigation",
            "type": "self-check",
            "activityKind": "geometry-investigation" if lesson.get("category") == "Γεωμετρία" else "transfer",
            "skill": lesson["title"],
            "difficulty": 3,
            "representation": "application",
            "prompt": (worksheet.get("C") or worksheet.get("B") or [f"Δημιούργησε ένα δικό σου παράδειγμα για το θέμα «{lesson['title']}» και αιτιολόγησέ το."])[0],
            "modelAnswer": solutions[-1].get("text", "Σύγκρινε τη στρατηγική σου με το λυμένο παράδειγμα και έλεγξε κάθε βήμα.") if solutions else "Σύγκρινε τη στρατηγική σου με το λυμένο παράδειγμα και έλεγξε κάθε βήμα.",
            "hints": ["Δοκίμασε πρώτα μια απλούστερη περίπτωση ή ένα πρόχειρο σχήμα.", "Αιτιολόγησε ποια ιδιότητα χρησιμοποιείς."],
        },
        {
            "id": f"{lesson['id']}-matching",
            "type": "matching",
            "skill": lesson["title"],
            "difficulty": 2,
            "representation": "multiple-representation",
            "prompt": "Αντιστοίχισε κάθε ερώτημα με τη σωστή απάντηση.",
            "pairs": [
                {"left": bank[0]["prompt"], "right": correct_0},
                {"left": bank[1]["prompt"], "right": correct_1},
            ] if len(bank) > 1 else [{"left": lesson["title"], "right": correct_0}],
            "explanation": "Κάθε ζεύγος συνδέει το ερώτημα με το αποτέλεσμα που προκύπτει από τον αντίστοιχο κανόνα.",
            "hints": ["Λύσε κάθε ερώτημα χωριστά πριν κάνεις την αντιστοίχιση.", "Έλεγξε αν κάθε απάντηση χρησιμοποιήθηκε ακριβώς μία φορά."],
        },
        {
            "id": f"{lesson['id']}-ordering",
            "type": "ordering",
            "skill": lesson["title"],
            "difficulty": 2,
            "representation": "procedural",
            "prompt": "Βάλε τα βήματα επίλυσης στη σωστή σειρά.",
            "steps": [
                "Καταγράφω τα δεδομένα και το ζητούμενο.",
                "Επιλέγω τον κατάλληλο κανόνα ή την ιδιότητα.",
                "Εφαρμόζω τον κανόνα και εκτελώ προσεκτικά τα βήματα.",
                "Ελέγχω αν το αποτέλεσμα απαντά στο ζητούμενο.",
            ],
            "explanation": "Η οργανωμένη επίλυση αρχίζει από τα δεδομένα, συνεχίζει με επιλογή και εφαρμογή του κανόνα και τελειώνει με έλεγχο.",
            "hints": ["Πρώτα πρέπει να γνωρίζεις τι δίνεται και τι ζητείται.", "Ο έλεγχος του αποτελέσματος γίνεται τελευταίος."],
        },
    ]

    # Six focused selected-response items plus all six richer activity formats.
    lesson.setdefault("practiceQuestions", [*bank[:6], *production])
    lesson["questionCount"] = len(lesson["practiceQuestions"])
    lesson.setdefault("guidedPractice", {
        "prompt": bank[-1]["prompt"] if bank else f"Εξήγησε με δικά σου λόγια το θέμα «{lesson['title']}».",
        "hint": "Γράψε πρώτα τη στρατηγική σου και μετά εκτέλεσε τους υπολογισμούς ή την κατασκευή.",
        "solution": bank[-1].get("explanation", "Σύγκρινε τη λύση σου με το λυμένο παράδειγμα." ) if bank else "Σύγκρινε την απάντησή σου με τα βασικά σημεία της θεωρίας.",
    })
    lesson.setdefault("learningSpecification", {
        "flow": ["ανάκληση", "λυμένο παράδειγμα", "καθοδηγούμενη εφαρμογή", "ανεξάρτητη εξάσκηση", "επανάληψη"],
        "masteryRequiresRepeatedSuccess": True,
        "secondAttemptWeight": 0.6,
    })


for lesson in LESSONS:
    _complete_g7_learning_design(lesson)

for lesson in LESSONS:
    if lesson["id"] in ADAPTIVE_PRACTICE:
        authored = ADAPTIVE_PRACTICE[lesson["id"]]
        rich_items = [item for item in lesson["practiceQuestions"] if item.get("type")]
        lesson["practiceQuestions"] = [*authored[:6], *rich_items]
        for index, question in enumerate(lesson["practiceQuestions"]):
            question.setdefault("representation", ("symbolic", "verbal", "application")[index % 3])
        lesson["questionCount"] = len(lesson["practiceQuestions"])


def _polish_g7_a1_1(lesson):
    """Hand-audited content for the first A Gymnasium lesson."""
    if lesson["id"] != "g7-a1-1":
        return

    lesson["theory"] = [
        "Οι φυσικοί αριθμοί είναι οι $0, 1, 2, 3, \\dots$ και τους χρησιμοποιούμε για μέτρηση και αρίθμηση.",
        "Η θέση ενός ψηφίου καθορίζει την αξία του: μονάδες, δεκάδες, εκατοντάδες, χιλιάδες κ.ο.κ. Στον αριθμό $4.628$, το ψηφίο $6$ έχει αξία $600$.",
        "Για να συγκρίνουμε δύο φυσικούς αριθμούς, συγκρίνουμε πρώτα το πλήθος των ψηφίων τους και, αν είναι ίδιο, τα ψηφία από αριστερά προς τα δεξιά.",
        "Για να διατάξουμε πολλούς αριθμούς, τους συγκρίνουμε και τους γράφουμε από τον μικρότερο προς τον μεγαλύτερο ή αντίστροφα, όπως ζητείται.",
        "Για στρογγυλοποίηση σε μια τάξη, κοιτάμε μόνο το αμέσως δεξιότερο ψηφίο: αν είναι $0,1,2,3,4$ κρατάμε το ψηφίο της τάξης, ενώ αν είναι $5,6,7,8,9$ το αυξάνουμε κατά $1$. Όλα τα δεξιότερα ψηφία γίνονται μηδενικά.",
    ]

    by_id = {question["id"]: question for question in lesson["practiceQuestions"]}
    feedback = {
        "g7-a1-1-q1": [
            "Διάλεξες το ίδιο το ψηφίο και όχι την αξία του. Το $6$ δεν βρίσκεται στις μονάδες.",
            "Θεώρησες ότι το $6$ βρίσκεται στις δεκάδες. Μέτρησε ξανά τις θέσεις από δεξιά.", "",
            "Θεώρησες ότι το $6$ βρίσκεται στις χιλιάδες. Στον αριθμό $4.628$, το ψηφίο των χιλιάδων είναι το $4$.",
        ],
        "g7-a1-1-q2": ["", "Αύξησες τη δεκάδα, σαν το ψηφίο των μονάδων να ήταν τουλάχιστον $5$. Εδώ είναι $4$.", "Άφησες τον αριθμό αμετάβλητο. Μετά τη στρογγυλοποίηση στη δεκάδα, το ψηφίο των μονάδων πρέπει να γίνει $0$.", "Στρογγυλοποίησες στην εκατοντάδα και όχι στη δεκάδα."],
        "g7-a1-1-q3": ["Το $999$ είναι τριψήφιο, ενώ υπάρχουν τετραψήφιοι αριθμοί στις επιλογές.", "", "Το $990$ είναι τριψήφιο, άρα μικρότερο από κάθε τετραψήφιο αριθμό.", "Το $1.000$ είναι τετραψήφιο, αλλά $1.001>1.000$ επειδή έχει μία μονάδα περισσότερο."],
        "g7-a1-1-q4": ["Μπέρδεψες το ψηφίο με την αξία του. Το $7$ δεν βρίσκεται στις μονάδες.", "Το $7$ δεν βρίσκεται στις δεκάδες· εκεί βρίσκεται το $4$.", "", "Το ψηφίο των χιλιάδων είναι το $2$, όχι το $7$."],
        "g7-a1-1-q5": ["", "Το $2.300$ δεν είναι πολλαπλάσιο του $1.000$, άρα δεν είναι αποτέλεσμα στρογγυλοποίησης στη χιλιάδα.", "Αυτό είναι στρογγυλοποίηση στην εκατοντάδα, όχι στη χιλιάδα.", "Αύξησες τις χιλιάδες, όμως το ψηφίο των εκατοντάδων είναι $3<5$."],
        "g7-a1-1-q6": ["Στις δεκάδες, ο πρώτος αριθμός έχει $1$ και ο δεύτερος $3$. Εφόσον $3>1$, ο δεύτερος είναι μεγαλύτερος.", "", "Οι αριθμοί δεν είναι ίσοι: διαφέρουν στις δεκάδες και στις μονάδες.", "Υπάρχουν αρκετά στοιχεία: συγκρίνουμε τα ψηφία από αριστερά."],
    }
    hints = {
        "g7-a1-1-q1": ["Διάβασε τον αριθμό από δεξιά: μονάδες, δεκάδες, εκατοντάδες.", "Το $6$ είναι το τρίτο ψηφίο από δεξιά."],
        "g7-a1-1-q2": ["Για στρογγυλοποίηση στη δεκάδα κοίτα μόνο το ψηφίο των μονάδων.", "Το ψηφίο των μονάδων είναι $4$, άρα η δεκάδα δεν αυξάνεται."],
        "g7-a1-1-q3": ["Σύγκρινε πρώτα πόσα ψηφία έχει κάθε αριθμός.", "Μετά σύγκρινε τους δύο τετραψήφιους αριθμούς."],
        "g7-a1-1-q4": ["Μέτρησε τις θέσεις από δεξιά προς τα αριστερά.", "Μετά τις μονάδες και τις δεκάδες έρχονται οι εκατοντάδες."],
        "g7-a1-1-q5": ["Για στρογγυλοποίηση στη χιλιάδα κοίτα το ψηφίο των εκατοντάδων.", "Το ψηφίο των εκατοντάδων είναι $3<5$."],
        "g7-a1-1-q6": ["Σύγκρινε τα ψηφία από αριστερά προς τα δεξιά.", "Η πρώτη διαφορά εμφανίζεται στις δεκάδες."],
    }
    for question_id in feedback:
        by_id[question_id]["optionFeedback"] = feedback[question_id]
        by_id[question_id]["hints"] = hints[question_id]

    by_id["g7-a1-1-input"]["acceptedAnswers"] = ["600"]
    by_id["g7-a1-1-input"]["hints"] = ["Εντόπισε τη θέση του $6$ μετρώντας από δεξιά.", "Το $6$ βρίσκεται στις εκατοντάδες, άρα πολλαπλασίασέ το με $100$."]
    by_id["g7-a1-1-fill"]["acceptedAnswers"] = ["380"]
    by_id["g7-a1-1-fill"]["hints"] = ["Κοίτα το ψηφίο των μονάδων.", "Επειδή $4<5$, κράτησε το $8$ στις δεκάδες και κάνε τις μονάδες $0$."]
    by_id["g7-a1-1-error"].update({
        "prompt": "Ο Νίκος λέει: «Στον αριθμό $4.628$ το ψηφίο $6$ έχει αξία $6$, επειδή είναι το ίδιο ψηφίο». Εντόπισε το λάθος και γράψε τη σωστή απάντηση.",
        "modelAnswer": "Ο Νίκος μπέρδεψε το ψηφίο με την αξία θέσης του. Το $6$ βρίσκεται στη θέση των εκατοντάδων, επομένως η αξία του είναι $6\\cdot100=600$.",
        "hints": ["Άλλο είναι το ψηφίο και άλλο η αξία που αποκτά από τη θέση του.", "Μέτρησε από δεξιά: μονάδες, δεκάδες, εκατοντάδες."],
    })
    by_id["g7-a1-1-investigation"].update({
        "modelAnswer": "Οι έξι δυνατοί αριθμοί είναι $258, 285, 528, 582, 825, 852$. Σε αύξουσα σειρά: $258<285<528<582<825<852$.",
        "hints": ["Διάλεξε διαδοχικά ποιο ψηφίο θα μπει στις εκατοντάδες και αντάλλαξε τα άλλα δύο.", "Πρέπει να προκύψουν $3!=6$ διαφορετικοί αριθμοί."],
    })
    by_id["g7-a1-1-ordering"].update({
        "prompt": "Βάλε τα βήματα για τη στρογγυλοποίηση του $4.582$ στην πλησιέστερη εκατοντάδα στη σωστή σειρά.",
        "steps": ["Εντοπίζω το ψηφίο των εκατοντάδων: είναι το $5$.", "Κοιτάζω το αμέσως δεξιότερο ψηφίο, δηλαδή το $8$ των δεκάδων.", "Επειδή $8\\ge5$, αυξάνω το ψηφίο των εκατοντάδων από $5$ σε $6$.", "Μηδενίζω δεκάδες και μονάδες και παίρνω $4.600$."],
        "explanation": "Εντοπίζουμε την τάξη, ελέγχουμε το αμέσως δεξιότερο ψηφίο, αποφασίζουμε αν θα αυξήσουμε και τέλος μηδενίζουμε τα δεξιότερα ψηφία.",
    })
    lesson["guidedPractice"] = {
        "prompt": "Γράψε σε αριθμό: «πέντε χιλιάδες εξήντα δύο».",
        "hint": "Χρησιμοποίησε πίνακα αξίας θέσης: χιλιάδες, εκατοντάδες, δεκάδες, μονάδες.",
        "solution": "Έχουμε $5$ χιλιάδες, $0$ εκατοντάδες, $6$ δεκάδες και $2$ μονάδες. Άρα ο αριθμός είναι $5.062$.",
    }
    lesson["assessment"]["questions"][0]["explanation"] = "Το $7$ βρίσκεται στις εκατοντάδες, επομένως η αξία του είναι $7\\cdot100=700$."
    lesson["assessment"]["questions"][2]["explanation"] = "Οι χιλιάδες και οι εκατοντάδες είναι ίδιες. Στις δεκάδες $3>1$, άρα $6.231>6.213$."
    lesson["assessment"]["questions"][4]["explanation"] = "Οι θέσεις είναι $5$ χιλιάδες, $0$ εκατοντάδες, $6$ δεκάδες και $2$ μονάδες, επομένως $5.062$."


for lesson in LESSONS:
    _polish_g7_a1_1(lesson)


def _polish_g7_a1_2(lesson):
    """Hand-audited content for operations with natural numbers."""
    if lesson["id"] != "g7-a1-2":
        return

    lesson["theory"] = [
        "Στην πρόσθεση, οι αριθμοί που προσθέτουμε λέγονται προσθετέοι και το αποτέλεσμα άθροισμα. Στον πολλαπλασιασμό λέγονται παράγοντες και το αποτέλεσμα γινόμενο.",
        "Η πρόσθεση και ο πολλαπλασιασμός είναι αντιμεταθετικές πράξεις: $\\alpha+\\beta=\\beta+\\alpha$ και $\\alpha\\cdot\\beta=\\beta\\cdot\\alpha$.",
        "Είναι επίσης προσεταιριστικές: $(\\alpha+\\beta)+\\gamma=\\alpha+(\\beta+\\gamma)$ και $(\\alpha\\cdot\\beta)\\cdot\\gamma=\\alpha\\cdot(\\beta\\cdot\\gamma)$.",
        "Η αφαίρεση δεν είναι ούτε αντιμεταθετική ούτε προσεταιριστική. Στους φυσικούς αριθμούς η $\\alpha-\\beta$ ορίζεται μόνο όταν $\\alpha\\ge\\beta$.",
        "Σε αριθμητική παράσταση εκτελούμε πρώτα τις πράξεις μέσα στις παρενθέσεις, έπειτα πολλαπλασιασμούς και τέλος προσθέσεις ή αφαιρέσεις από αριστερά προς τα δεξιά.",
        "Η επιμεριστική ιδιότητα συνδέει τον πολλαπλασιασμό με την πρόσθεση και την αφαίρεση: $\\alpha(\\beta+\\gamma)=\\alpha\\beta+\\alpha\\gamma$ και, όταν $\\beta\\ge\\gamma$, $\\alpha(\\beta-\\gamma)=\\alpha\\beta-\\alpha\\gamma$.",
    ]
    lesson["plan"]["objectives"] = [
        "Ο μαθητής να εκτελεί σωστά πρόσθεση, αφαίρεση και πολλαπλασιασμό φυσικών αριθμών.",
        "Να εφαρμόζει σωστά την προτεραιότητα πράξεων, με και χωρίς παρενθέσεις.",
        "Να αναγνωρίζει και να χρησιμοποιεί την αντιμεταθετική, την προσεταιριστική και την επιμεριστική ιδιότητα.",
        "Να ελέγχει αν το αποτέλεσμα ενός υπολογισμού είναι εύλογο.",
    ]
    lesson["plan"]["materials"] = ["Καρτέλες αριθμητικών παραστάσεων", "Φύλλο εργασίας", "Πίνακας προτεραιότητας πράξεων"]
    lesson["plan"]["formativeAssessment"] = [
        "Υπολόγισε $12+3\\times4$ και αιτιολόγησε ποια πράξη εκτελείται πρώτη.",
        "Σύγκρινε τα $6+2\\times3$ και $(6+2)\\times3$: γιατί δίνουν διαφορετικά αποτελέσματα;",
        "Εξήγησε το λάθος στη λύση $10+2\\times5=12\\times5=60$.",
    ]
    lesson["plan"]["exitTicket"] = [
        "Υπολόγισε νοερά το $8\\times99$ με την επιμεριστική ιδιότητα.",
        "Γράψε δύο παραστάσεις με τους ίδιους αριθμούς αλλά διαφορετική θέση παρενθέσεων και διαφορετικό αποτέλεσμα.",
        "Βαθμολόγησε τη βεβαιότητά σου από $1$ έως $4$ και σημείωσε ποιον κανόνα χρειάζεται να ξαναδείς.",
    ]

    # Remove the ambiguity: both associativity and commutativity hold for
    # multiplication but not for subtraction.
    property_question = lesson["assessment"]["questions"][4]
    property_question.update({
        "prompt": "Ποια ιδιότητα εκφράζει η ισότητα $\\alpha\\cdot\\beta=\\beta\\cdot\\alpha$;",
        "options": ["Προσεταιριστική", "Αντιμεταθετική", "Επιμεριστική", "Ουδέτερο στοιχείο"],
        "correct": 1,
        "explanation": "Η αλλαγή της σειράς των παραγόντων χωρίς αλλαγή του γινομένου είναι η αντιμεταθετική ιδιότητα.",
    })

    by_id = {question["id"]: question for question in lesson["practiceQuestions"]}
    refinements = {
        "g7-a1-2-q2": {
            "hints": ["Οι πράξεις μέσα στην παρένθεση προηγούνται.", "Υπολόγισε πρώτα $3+2$ και έπειτα πολλαπλασίασε το αποτέλεσμα με $5$."],
            "optionFeedback": ["Πρόσθεσες το $5$ στο γινόμενο $3\\times4$, αλλά η παράσταση έχει παρένθεση.", "", "Αγνόησες την παρένθεση και έκανες πρώτα $5\\times3$.", "Πολλαπλασίασες το $5$ μόνο με το $2$ και παρέλειψες το $3$."],
        },
        "g7-a1-2-q3": {
            "hints": ["Αφαίρεσε πρώτα $10$ και μετά ακόμη $5$.", "$48-10=38$ και απομένει να αφαιρέσεις $5$."],
            "optionFeedback": ["", "Αφαίρεσες μόνο το $5$ και παρέλειψες τη δεκάδα του $15$.", "Αφαίρεσες $25$ αντί για $15$.", "Πρόσθεσες τους δύο αριθμούς αντί να αφαιρέσεις."],
        },
        "g7-a1-2-q4": {
            "hints": ["Ο πολλαπλασιασμός προηγείται της πρόσθεσης.", "Υπολόγισε $2\\times5$ και μετά πρόσθεσε $10$."],
            "optionFeedback": ["Υπολόγισες από αριστερά: $(10+2)\\times5$. Η παράσταση όμως δεν έχει παρένθεση.", "", "Έκανες λανθασμένα $2\\times5=7$.", "Πρόσθεσες $10+2$ και παρέλειψες τον πολλαπλασιασμό με $5$."],
        },
        "g7-a1-2-q5": {
            "hints": ["Η παρένθεση εκτελείται πριν από τον πολλαπλασιασμό.", "Υπολόγισε $4+1$ και πολλαπλασίασε το αποτέλεσμα με $6$."],
            "optionFeedback": ["Πρόσθεσες $1$ στο $4\\times6$, αγνοώντας την παρένθεση.", "", "Πρόσθεσες το $4+1$ και μετά πρόσθεσες, αντί να πολλαπλασιάσεις, το $6$.", "Υπολόγισες μόνο $4\\times6$ και παρέλειψες το $1$."],
        },
        "g7-a1-2-q6": {
            "hints": ["Γράψε $99=100-1$.", "Εφάρμοσε $9(100-1)=9\\times100-9\\times1$."],
            "optionFeedback": ["", "Υπολόγισες μόνο $9\\times100$ και δεν αφαίρεσες $9$.", "Αντιμετώπισες το $99$ σαν $110$ ή τοποθέτησες λάθος το μηδενικό.", "Αφαίρεσες $99$ από $900$, αντί να αφαιρέσεις $9$."],
        },
    }
    for question_id, values in refinements.items():
        by_id[question_id].update(values)

    by_id["g7-a1-2-input"].update({"acceptedAnswers": ["24"], "hints": ["Ο πολλαπλασιασμός προηγείται της πρόσθεσης.", "Υπολόγισε πρώτα $3\\times4$."]})
    by_id["g7-a1-2-fill"].update({"acceptedAnswers": ["25"], "hints": ["Ξεκίνα από την παρένθεση.", "Μετά το $3+2=5$, απομένει $5\\times5$."]})
    by_id["g7-a1-2-error"].update({
        "prompt": "Η Μαρία υπολόγισε $10+2\\times5=12\\times5=60$. Εντόπισε το λάθος και διόρθωσε τη λύση.",
        "modelAnswer": "Η Μαρία έκανε πρώτα την πρόσθεση, παρότι δεν υπάρχει παρένθεση. Πρώτα $2\\times5=10$ και έπειτα $10+10=20$.",
        "hints": ["Ποια πράξη έχει προτεραιότητα όταν δεν υπάρχουν παρενθέσεις;", "Μην αλλάζεις την παράσταση προσθέτοντας νοερά παρένθεση."],
    })
    by_id["g7-a1-2-investigation"].update({
        "modelAnswer": "Πρώτα $2\\times4=8$, μετά η παρένθεση: $5+8=13$. Έπειτα $3\\times13=39$ και τέλος $39-6=33$.",
        "hints": ["Μέσα στην παρένθεση υπάρχει ένας πολλαπλασιασμός που προηγείται.", "Μετά την παρένθεση, εκτέλεσε τον εξωτερικό πολλαπλασιασμό και στο τέλος την αφαίρεση."],
    })
    by_id["g7-a1-2-ordering"].update({
        "prompt": "Βάλε στη σωστή σειρά τα βήματα για τον υπολογισμό $3\\times(5+2\\times4)-6$.",
        "steps": ["Υπολογίζω $2\\times4=8$ μέσα στην παρένθεση.", "Υπολογίζω $5+8=13$ και κλείνω την παρένθεση.", "Υπολογίζω $3\\times13=39$.", "Υπολογίζω $39-6=33$."],
        "explanation": "Οι παρενθέσεις προηγούνται, αλλά και μέσα σε αυτές τηρείται η προτεραιότητα του πολλαπλασιασμού. Η τελική αφαίρεση γίνεται τελευταία.",
        "hints": ["Ξεκίνα από την εσωτερική πράξη με τη μεγαλύτερη προτεραιότητα.", "Η αφαίρεση του $6$ είναι το τελευταίο βήμα."],
    })
    lesson["guidedPractice"] = {
        "prompt": "Υπολόγισε νοερά το $7\\times102$ χρησιμοποιώντας την επιμεριστική ιδιότητα.",
        "hint": "Γράψε $102=100+2$ και μοίρασε τον πολλαπλασιασμό στο άθροισμα.",
        "solution": "$7\\times102=7\\times(100+2)=7\\times100+7\\times2=700+14=714$.",
    }
    lesson["solutions"][2]["text"] = "1) Πρώτα $2\\times4=8$, μετά $5+8=13$, έπειτα $3\\times13=39$ και τέλος $39-6=33$. 2) Π.χ. $5-2=3$, ενώ το $2-5$ δεν ορίζεται στο σύνολο των φυσικών αριθμών· άρα η αφαίρεση δεν είναι αντιμεταθετική."


for lesson in LESSONS:
    _polish_g7_a1_2(lesson)


def _polish_g7_a1_3(lesson):
    """Hand-audited, textbook-aligned lesson on powers of natural numbers."""
    if lesson["id"] != "g7-a1-3":
        return

    lesson["theory"] = [
        "Το γινόμενο $\\alpha\\cdot\\alpha\\cdot\\ldots\\cdot\\alpha$ με $\\nu$ ίσους παράγοντες λέγεται δύναμη του $\\alpha$ στη $\\nu$ και γράφεται $\\alpha^{\\nu}$. Το $\\alpha$ λέγεται βάση και το $\\nu$ εκθέτης.",
        "Η δύναμη $\\alpha^2$ λέγεται τετράγωνο του $\\alpha$ και η $\\alpha^3$ κύβος του $\\alpha$. Επίσης $\\alpha^1=\\alpha$ και $1^{\\nu}=1$.",
        "Η δύναμη δεν είναι πολλαπλασιασμός βάσης και εκθέτη: $2^3=2\\cdot2\\cdot2=8$, ενώ $2\\cdot3=6$.",
        "Η δύναμη $10^{\\nu}$ γράφεται ως $1$ ακολουθούμενο από $\\nu$ μηδενικά. Για παράδειγμα, $10^4=10.000$.",
        "Σε αριθμητική παράσταση η σειρά είναι: πρώτα δυνάμεις, έπειτα πολλαπλασιασμοί και διαιρέσεις και τέλος προσθέσεις και αφαιρέσεις. Μέσα στις παρενθέσεις εφαρμόζουμε την ίδια σειρά.",
        "Κάθε φυσικός αριθμός μπορεί να αναπτυχθεί με δυνάμεις του $10$: $7.604=7\\cdot10^3+6\\cdot10^2+0\\cdot10^1+4$.",
    ]
    lesson["example"] = {
        "title": "Λυμένο παράδειγμα: Δυνάμεις και προτεραιότητα πράξεων",
        "text": "Να υπολογιστεί η παράσταση $(2+3)^3-8\\cdot3^2$. **Βήμα 1**: Παρένθεση: $2+3=5$. **Βήμα 2**: Δυνάμεις: $5^3=125$ και $3^2=9$. **Βήμα 3**: Πολλαπλασιασμός: $8\\cdot9=72$. **Βήμα 4**: Αφαίρεση: $125-72=53$.",
    }
    lesson["plan"].update({
        "objectives": ["Να αναγνωρίζει βάση και εκθέτη και να γράφει επαναλαμβανόμενο γινόμενο ως δύναμη.", "Να υπολογίζει τετράγωνα, κύβους και μικρές δυνάμεις φυσικών αριθμών.", "Να χρησιμοποιεί τις δυνάμεις του $10$ και να αναπτύσσει φυσικό αριθμό με αυτές.", "Να εφαρμόζει σωστά την προτεραιότητα πράξεων σε αριθμητικές παραστάσεις με δυνάμεις."],
        "duration": "45 λεπτά",
        "materials": ["Καρτέλες γινομένων και δυνάμεων", "Τετραγωνισμένο χαρτί ή κύβοι", "Πίνακας αξίας θέσης"],
        "overview": "Οι μαθητές περνούν από τετράγωνα και κύβους ως οπτικά μοντέλα στον συμβολισμό της δύναμης, στις δυνάμεις του $10$ και στην προτεραιότητα πράξεων.",
        "formativeAssessment": ["Γράψε το $4\\cdot4\\cdot4$ ως δύναμη και ονόμασε βάση και εκθέτη.", "Σύγκρινε τα $3^2$ και $3\\cdot2$ και εξήγησε γιατί διαφέρουν.", "Υπολόγισε $2+3\\cdot2^2$ εξηγώντας τη σειρά των πράξεων."],
        "exitTicket": ["Γράψε το $10^5$ ως φυσικό αριθμό.", "Ανάπτυξε το $3.042$ με δυνάμεις του $10$.", "Βαθμολόγησε τη βεβαιότητά σου από $1$ έως $4$ και σημείωσε ποιο σημείο χρειάζεται επανάληψη."],
    })
    lesson["attention"] = ["Μην μπερδεύεις το $\\alpha^{\\nu}$ με το $\\alpha\\cdot\\nu$.", "Στις αριθμητικές παραστάσεις οι δυνάμεις υπολογίζονται πριν από τους πολλαπλασιασμούς.", "Οι εκφράσεις $(\\alpha+\\beta)^2$ και $\\alpha^2+\\beta^2$ δεν είναι γενικά ίσες."]
    lesson["worksheet"] = {
        "A": ["Γράψε ως δύναμη το $5\\cdot5\\cdot5\\cdot5$ και υπολόγισέ την.", "Υπολόγισε τα $6^2$, $4^3$ και $10^5$."],
        "B": ["Υπολόγισε $3\\cdot5^2+2^2$ με τη σωστή σειρά πράξεων.", "Σύγκρινε τα $(6+5)^2$ και $6^2+5^2$. Τι παρατηρείς;"],
        "C": ["Γράψε το ανάπτυγμα του $34.720$ με δυνάμεις του $10$.", "Βρες δύο διαφορετικές δυνάμεις φυσικών αριθμών που έχουν τιμή $64$."],
    }
    lesson["solutions"] = [
        {"title": "Επίπεδο Α", "text": "1) $5^4=625$. 2) $6^2=36$, $4^3=64$, $10^5=100.000$."},
        {"title": "Επίπεδο Β", "text": "1) $3\\cdot25+4=75+4=79$. 2) $(6+5)^2=11^2=121$, ενώ $6^2+5^2=36+25=61$, άρα δεν είναι ίσα."},
        {"title": "Επίπεδο Γ", "text": "1) $34.720=3\\cdot10^4+4\\cdot10^3+7\\cdot10^2+2\\cdot10^1+0$. 2) Για παράδειγμα, $8^2=64$ και $4^3=64$."},
    ]
    lesson["recap"] = {"keyPoints": ["Η βάση είναι ο επαναλαμβανόμενος παράγοντας και ο εκθέτης το πλήθος των παραγόντων.", "$\\alpha^2$ λέγεται τετράγωνο και $\\alpha^3$ κύβος.", "$10^{\\nu}$ είναι $1$ με $\\nu$ μηδενικά.", "Στις αριθμητικές παραστάσεις υπολογίζουμε πρώτα τις δυνάμεις.", "Οι δυνάμεις του $10$ περιγράφουν την αξία θέσης των ψηφίων."], "nextLessonIds": ["g7-a1-4"], "furtherStudy": ["Βρες όλους τους φυσικούς αριθμούς μικρότερους από $200$ που είναι ταυτόχρονα τετράγωνα και κύβοι."]}

    by_id = {question["id"]: question for question in lesson["practiceQuestions"]}
    selected = {
        "g7-a1-3-q2": ("Πόσο κάνει $5^1$;", ["1", "5", "0", "25"], 1, "$5^1=5$: η πρώτη δύναμη ενός αριθμού είναι ο ίδιος ο αριθμός.", ["Ο εκθέτης $1$ σημαίνει έναν παράγοντα.", "Γράψε τη δύναμη ως γινόμενο με έναν μόνο παράγοντα."], ["Αυτό θα ίσχυε για δύναμη του $1$, όχι για $5^1$.", "", "Ο εκθέτης δεν μηδενίζει τη βάση.", "Αυτό είναι $5^2$, όχι $5^1$.!"]),
        "g7-a1-3-q3": ("Πώς γράφεται ως δύναμη το $3\\cdot3\\cdot3\\cdot3$;", ["$3^4$", "$4^3$", "$3\\cdot4$", "$12^1$"], 0, "Η βάση είναι $3$ και εμφανίζεται ως παράγοντας $4$ φορές, άρα $3^4$.", ["Η βάση είναι ο αριθμός που επαναλαμβάνεται.", "Μέτρησε πόσες φορές εμφανίζεται ο παράγοντας $3$."], ["", "Αντάλλαξες βάση και εκθέτη.", "Μπέρδεψες τη δύναμη με το γινόμενο βάσης και εκθέτη.", "Το $12^1$ έχει ίδια τιμή αλλά δεν αποδίδει το επαναλαμβανόμενο γινόμενο ως ζητούμενη δύναμη."]),
        "g7-a1-3-q4": ("Πόσο κάνει $10^4$;", ["40", "1.000", "10.000", "100.000"], 2, "$10^4$ είναι $1$ ακολουθούμενο από $4$ μηδενικά: $10.000$.", ["Στις δυνάμεις του $10$, ο εκθέτης δείχνει το πλήθος των μηδενικών.", "Γράψε $10\\cdot10\\cdot10\\cdot10$."], ["Πολλαπλασίασες βάση και εκθέτη.", "Έγραψες μόνο $3$ μηδενικά.", "", "Έγραψες $5$ μηδενικά."]),
        "g7-a1-3-q5": ("Πόσο κάνει $(2+3)^2+3\\cdot2^2$;", ["19", "31", "37", "49"], 2, "$(2+3)^2+3\\cdot2^2=5^2+3\\cdot4=25+12=37$.", ["Υπολόγισε πρώτα την παρένθεση και όλες τις δυνάμεις.", "Μετά εκτέλεσε τον πολλαπλασιασμό και στο τέλος την πρόσθεση."], ["Πιθανότατα υπολόγισες $(2+3)^2$ ως $2+3^2$.", "Έκανες λάθος στον εξωτερικό πολλαπλασιασμό ή στην τελική πρόσθεση.", "", "Ύψωσες ολόκληρο το άθροισμα $5+2$ στο τετράγωνο."]),
        "g7-a1-3-q6": ("Ποιος αριθμός έχει ανάπτυγμα $7\\cdot10^3+6\\cdot10^2+0\\cdot10+4$;", ["7.064", "7.604", "7.640", "76.004"], 1, "$7.000+600+0+4=7.604$.", ["Αντιστοίχισε κάθε συντελεστή στη θέση του.", "Έχουμε $7$ χιλιάδες, $6$ εκατοντάδες, $0$ δεκάδες και $4$ μονάδες."], ["Τοποθέτησες το $6$ στις δεκάδες αντί στις εκατοντάδες.", "", "Τοποθέτησες το $4$ στις δεκάδες αντί στις μονάδες.", "Μετέφερες το $7$ στη θέση των δεκάδων χιλιάδων."]),
    }
    for question_id, (prompt, options, correct, explanation, hints, feedback) in selected.items():
        by_id[question_id].update({"prompt": prompt, "options": options, "correct": correct, "explanation": explanation, "hints": hints, "optionFeedback": feedback})

    by_id["g7-a1-3-input"].update({"acceptedAnswers": ["16"], "hints": ["Ο εκθέτης $4$ σημαίνει τέσσερις ίσους παράγοντες.", "Υπολόγισε $2\\cdot2\\cdot2\\cdot2$."]})
    by_id["g7-a1-3-fill"].update({"acceptedAnswers": ["5"], "hints": ["Ο εκθέτης είναι $1$.", "Η πρώτη δύναμη ενός αριθμού είναι ο ίδιος ο αριθμός."]})
    by_id["g7-a1-3-error"].update({"prompt": "Ο Πέτρος έγραψε $2^3=2\\cdot3=6$. Εντόπισε το λάθος και διόρθωσέ το.", "modelAnswer": "Ο εκθέτης δείχνει πόσες φορές χρησιμοποιείται η βάση ως παράγοντας: $2^3=2\\cdot2\\cdot2=8$, όχι $2\\cdot3$.", "hints": ["Ο εκθέτης δεν είναι δεύτερος παράγοντας.", "Γράψε τρεις ίσους παράγοντες με βάση το $2$."]})
    by_id["g7-a1-3-investigation"].update({"modelAnswer": "Στο $15$ο τετράγωνο υπάρχουν $2^{15-1}=2^{14}=16.384$ κόκκοι.", "hints": ["Στο πρώτο τετράγωνο είναι $2^0$, στο δεύτερο $2^1$· βρες το μοτίβο.", "Ο εκθέτης είναι κατά $1$ μικρότερος από τον αριθμό της θέσης."]})
    by_id["g7-a1-3-ordering"].update({"prompt": "Βάλε στη σωστή σειρά τα βήματα για την παράσταση $(2+3)^3-8\\cdot3^2$.", "steps": ["Υπολογίζω την παρένθεση: $2+3=5$.", "Υπολογίζω τις δυνάμεις: $5^3=125$ και $3^2=9$.", "Υπολογίζω τον πολλαπλασιασμό: $8\\cdot9=72$.", "Εκτελώ την αφαίρεση: $125-72=53$."], "explanation": "Παρένθεση, δυνάμεις, πολλαπλασιασμός και τέλος αφαίρεση.", "hints": ["Μέσα στην παρένθεση εφαρμόζεται πρώτα η πρόσθεση που περιέχει.", "Μετά τις δυνάμεις προηγείται ο πολλαπλασιασμός της αφαίρεσης."]})
    lesson["guidedPractice"] = {"prompt": "Γράψε το $7.604$ σε αναπτυγμένη μορφή με δυνάμεις του $10$.", "hint": "Αντιστοίχισε χιλιάδες, εκατοντάδες, δεκάδες και μονάδες στις $10^3,10^2,10^1,10^0$.", "solution": "$7.604=7\\cdot10^3+6\\cdot10^2+0\\cdot10^1+4$."}
    lesson["assessment"] = {"durationMinutes": 12, "questions": [
        Q("Πόσο κάνει $4^2$;", ["8", "16", "6", "42"], 1, "$4^2=4\\cdot4=16$."),
        Q("Πόσο κάνει $10^5$;", ["50", "10.000", "100.000", "1.000.000"], 2, "$10^5$ είναι $1$ με $5$ μηδενικά: $100.000$."),
        Q("Πόσο κάνει $2^3+3\\cdot2^2$;", ["14", "20", "28", "40"], 1, "$2^3+3\\cdot2^2=8+3\\cdot4=8+12=20$."),
        Q("Ποιο είναι το ανάπτυγμα του $7.604$;", ["$7\\cdot10^3+6\\cdot10^2+4$", "$7\\cdot10^2+6\\cdot10+4$", "$7\\cdot10^4+6\\cdot10^3+4$", "$76\\cdot10^2+4\\cdot10$"], 0, "$7.604=7.000+600+4=7\\cdot10^3+6\\cdot10^2+4$."),
        Q("Ποια ισότητα είναι σωστή;", ["$3^2=3\\cdot2$", "$(3+2)^2=3^2+2^2$", "$4^3=4\\cdot4\\cdot4$", "$10^4=1.000$"], 2, "Ο εκθέτης $3$ δηλώνει τρεις ίσους παράγοντες: $4^3=4\\cdot4\\cdot4$."),
    ]}


for lesson in LESSONS:
    _polish_g7_a1_3(lesson)


# Κάθε μάθημα μετά το πρώτο ανακαλεί μία δεξιότητα από το αμέσως προηγούμενο.
g7_lessons = sorted((lesson for lesson in LESSONS if lesson.get("gradeId") == "g7"), key=lambda item: item["order"])
for index, lesson in enumerate(g7_lessons):
    if index:
        previous = g7_lessons[index - 1]
        source = previous["practiceQuestions"][0]
        recall = dict(source)
        recall["id"] = f"{lesson['id']}-recall-{previous['id']}"
        recall["recall"] = True
        recall["sourceLessonId"] = previous["id"]
        recall["skill"] = f"Επανάληψη: {previous['title']}"
        current = lesson["practiceQuestions"]
        removable = next((position for position, question in enumerate(current) if not question.get("type")), 0)
        lesson["practiceQuestions"] = [question for position, question in enumerate(current) if position != removable][:11] + [recall]
    elif len(lesson["practiceQuestions"]) < 10:
        lesson["practiceQuestions"].append(dict(lesson["practiceQuestions"][-1], id=f"{lesson['id']}-transfer-2"))
    lesson["questionCount"] = len(lesson["practiceQuestions"])


# Τα δύο αρχικά συγκεντρωτικά μαθήματα της Α΄ Γυμνασίου αντικαταστάθηκαν
# από τις αναλυτικές, επίσημα αριθμημένες ενότητες Β1.1–Β1.13.
LESSONS = [lesson for lesson in LESSONS if lesson["id"] not in {"g7-6-1", "g7-6-2"}]


def all_docs():
    return GRADES, LESSONS


def all_books():
    return BOOKS
